#include <iostream>

class Fraction {
private:
    int num;
    int den;
public:
    Fraction(int n = 0, int d = 1) : num(n), den(d) {}

    int& operator[](int index) {
        return (index == 0) ? num : den;
    }

    const int& operator[](int index) const {
        return (index == 0) ? num : den;
    }

    Fraction& operator+=(const Fraction& other) {
        num = num * other.den + other.num * den;
        den = den * other.den;
        return *this;
    }

    void print() const {
        std::cout << num << "/" << den << "\n";
    }
};

int main() {
    Fraction f(1, 2);
    f += Fraction(3, 2);
    f.print();

    f[0] = 7;
    f[1] = 8;
    f.print();
    return 0;
}

#include <iostream>
#include <numeric>

class Rational {
private:
    int numerator;
    int denominator;

    static int gcd(int a, int b) {
        a = std::abs(a);
        b = std::abs(b);
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    void reduce() {
        if (denominator < 0) {
            numerator = -numerator;
            denominator = -denominator;
        }
        int g = gcd(numerator, denominator);
        if (g > 1) {
            numerator /= g;
            denominator /= g;
        }
    }

public:
    Rational(int num = 0, int den = 1) : numerator(num), denominator(den) {
        reduce();
    }

    Rational& operator++() {
        numerator += denominator;
        return *this;
    }

    Rational operator++(int) {
        Rational temp = *this;
        numerator += denominator;
        return temp;
    }

    friend std::ostream& operator<<(std::ostream& out, const Rational& r) {
        if (r.denominator == 1)
            out << r.numerator;
        else
            out << r.numerator << "/" << r.denominator;
        return out;
    }

    friend Rational operator+(const Rational& r1, const Rational& r2) {
        return Rational(r1.numerator * r2.denominator + r2.numerator * r1.denominator,
                        r1.denominator * r2.denominator);
    }
};

int main() {
    Rational r(3, 4);
    Rational prev = r++;
    std::cout << "prev: " << prev << ", current: " << r << "\n";
    std::cout << "1 + r: " << (1 + r) << "\n";
    return 0;
}
